// ============================================
// SYNORA - Nora Baustein N0 einbauen (Grundlage)
// ============================================
// Legt die neuen Nora-Dateien an und meldet Nora in server.js an.
// Kiara wird nicht angefasst.
//
//   NEU      src/nora/config.js
//            src/nora/models/firmaPflicht.js, Firma.js, Verbrauch.js
//            src/nora/services/verbrauch.js, firmaZugriff.js, freischalten.js
//            src/nora/routes/index.js
//            src/routes/nora.js
//            scripts/noraFreischalten.js, scripts/noraProbe.js
//   GEAENDERT src/server.js   (eine Zeile: ladeRoute('nora', '/api/nora'))
//
// Alles oder nichts: Sicherung von server.js zuerst, Gegenprobe,
// Syntaxpruefung, Ladeprobe in einem eigenen Prozess. Geht etwas
// schief, wird alles zurueckgestellt.
//
// Aufruf im Ordner synora-backend-main:
//   node noraGrundlage.js
// ============================================

'use strict';

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const WURZEL = process.cwd();

const DATEIEN = {
  "src/nora/config.js": "// ============================================\n// SYNORA - Nora: Limits, Kostenbremse, Reserve pro Aufgabe\n// ============================================\n// Alle Zahlen kommen aus Railway-Variablen. Fehlt eine Variable,\n// gilt der Wert, der am 14.11.2026 abgemacht wurde\n// (claude/nora-gewerbe-analyse.md, Teil 14).\n//\n// Die Preisseite zeigt nur zwei davon: Pruefungen und Experten-\n// pruefungen. Die anderen gelten als faire Nutzung. Die Kosten-\n// bremse pro Firma schuetzt den Gewinn, auch wenn eine Schaetzung\n// unten nicht stimmt.\n// ============================================\n\n'use strict';\n\nfunction zahl(name, vorgabe, minimum = 0) {\n  const roh = process.env[name];\n  if (roh === undefined || roh === null || String(roh).trim() === '') return vorgabe;\n  const n = Number(roh);\n  if (!Number.isFinite(n) || n < minimum) {\n    console.warn(`[nora] ${name}=\"${roh}\" ist ungueltig - nehme ${vorgabe}`);\n    return vorgabe;\n  }\n  return n;\n}\n\n// Wie viel eine Firma pro Monat darf.\nconst LIMITS = Object.freeze({\n  pruefungen: zahl('NORA_PRUEFUNGEN', 200, 0),\n  experten: zahl('NORA_EXPERTEN', 50, 0),       // Teil der Pruefungen\n  offerten: zahl('NORA_OFFERTEN', 150, 0),\n  dokumente: zahl('NORA_DOKUMENTE', 500, 0),\n  fotos: zahl('NORA_FOTOS', 100, 0),\n  preise: zahl('NORA_PREISE', 300, 0),\n  artefakte: zahl('NORA_ARTEFAKTE', 100, 0),\n  akten: zahl('NORA_AKTEN', 150, 0)\n});\n\nconst ZAEHLER = Object.freeze(Object.keys(LIMITS));\n\n// Personen pro Firma (der Inhaber zaehlt mit).\nconst PERSONEN = zahl('NORA_PERSONEN', 3, 1);\n\n// Kostenbremse pro Firma und Monat, in Franken.\nconst BREMSE_CHF = zahl('NORA_BREMSE_CHF', 120, 0);\n\n// Jede Aufgabe belastet einen oder mehrere Zaehler und reserviert\n// vorab hoechstens so viel Geld. Nach der Arbeit wird die Reserve\n// auf die echten Kosten korrigiert (verbrauch.abrechnen).\n// Die Reserve liegt bewusst ueber der Schaetzung aus Teil 8, damit\n// die Bremse auch bei einem teuren Durchlauf haelt.\nconst AUFGABEN = Object.freeze({\n  pruefung: Object.freeze({ zaehler: ['pruefungen'], reserveChf: 0.40 }),\n  expertenpruefung: Object.freeze({ zaehler: ['pruefungen', 'experten'], reserveChf: 0.60 }),\n  offerte: Object.freeze({ zaehler: ['offerten'], reserveChf: 0.08 }),\n  dokument: Object.freeze({ zaehler: ['dokumente'], reserveChf: 0.02 }),\n  foto: Object.freeze({ zaehler: ['fotos'], reserveChf: 0.02 }),\n  preis: Object.freeze({ zaehler: ['preise'], reserveChf: 0.02 }),\n  artefakt: Object.freeze({ zaehler: ['artefakte'], reserveChf: 0.15 }),\n  akte: Object.freeze({ zaehler: ['akten'], reserveChf: 0.15 })\n});\n\n// Abo-Stufen, mit denen eine Firma Nora nutzen darf.\nconst ABO_STUFEN = Object.freeze(['pilot', 'nora']);\n\n// Ab welchem Anteil Nora einen Hinweis zeigt.\nconst WARNUNG_AB = 0.8;\n\nmodule.exports = { LIMITS, ZAEHLER, PERSONEN, BREMSE_CHF, AUFGABEN, ABO_STUFEN, WARNUNG_AB, zahl };\n",
  "src/nora/models/firmaPflicht.js": "// ============================================\n// SYNORA - Nora: Firmenpflicht fuer jede Abfrage\n// ============================================\n// Nora speichert Offerten, Preise und Konditionen fremder Firmen.\n// Die Preise einer Firma duerfen NIE bei einer anderen auftauchen.\n//\n// Dieses Plugin haengt an jedem Nora-Modell mit firmaId und lehnt\n// jede Abfrage ab, die keine eindeutige firmaId enthaelt:\n//\n//   erlaubt      { firmaId: <ObjectId> }   oder 24-stellige Hex-Zeichenkette\n//   abgelehnt    {}  |  { firmaId: { $exists: true } }  |  { firmaId: { $in: [...] } }\n//\n// Ausserdem darf kein Update die firmaId aendern, und jede\n// Aggregation muss mit { $match: { firmaId: <ObjectId> } } beginnen.\n//\n// NICHT benutzen: Model.bulkWrite() und Model.collection.* - die\n// laufen an Mongoose vorbei und damit an diesem Schutz.\n// ============================================\n\n'use strict';\n\nconst mongoose = require('mongoose');\n\nconst ABFRAGEN = [\n  'find', 'findOne', 'findOneAndUpdate', 'findOneAndDelete', 'findOneAndReplace',\n  'updateOne', 'updateMany', 'replaceOne', 'deleteOne', 'deleteMany',\n  'countDocuments', 'distinct'\n];\n\nconst MIT_UPDATE = new Set(['findOneAndUpdate', 'findOneAndReplace', 'updateOne', 'updateMany', 'replaceOne']);\n\nfunction istEindeutigeFirma(wert) {\n  if (wert instanceof mongoose.Types.ObjectId) return true;\n  if (typeof wert === 'string' && /^[0-9a-fA-F]{24}$/.test(wert)) return true;\n  return false;\n}\n\nfunction filterHatFirma(filter) {\n  return !!(filter && Object.prototype.hasOwnProperty.call(filter, 'firmaId') && istEindeutigeFirma(filter.firmaId));\n}\n\nfunction updateBeruehrtFirma(update) {\n  if (!update || typeof update !== 'object') return false;\n  if (Array.isArray(update)) return true; // Pipeline-Updates sind hier nicht vorgesehen\n  for (const [schluessel, wert] of Object.entries(update)) {\n    if (schluessel === 'firmaId') return true;\n    if (schluessel.startsWith('$') && wert && typeof wert === 'object' &&\n        Object.prototype.hasOwnProperty.call(wert, 'firmaId')) return true;\n  }\n  return false;\n}\n\nfunction firmaPflicht(schema) {\n  schema.pre(ABFRAGEN, function () {\n    const art = this.op;\n    if (!filterHatFirma(this.getFilter())) {\n      throw new Error(`NORA: ${art} ohne eindeutige firmaId verweigert`);\n    }\n    if (MIT_UPDATE.has(art) && updateBeruehrtFirma(this.getUpdate())) {\n      throw new Error(`NORA: ${art} darf die firmaId nicht aendern`);\n    }\n  });\n\n  schema.pre('aggregate', function () {\n    const erste = this.pipeline()[0];\n    if (!erste || !erste.$match || !filterHatFirma(erste.$match)) {\n      throw new Error('NORA: Aggregation muss mit $match auf eine firmaId beginnen');\n    }\n  });\n}\n\nmodule.exports = { firmaPflicht, filterHatFirma, istEindeutigeFirma, updateBeruehrtFirma };\n",
  "src/nora/models/Firma.js": "// ============================================\n// SYNORA - Nora: Firma\n// ============================================\n// Eine Firma ist der Kunde von Nora. Ihr gehoeren die Personen,\n// die Projekte, die Dokumente und das Gedaechtnis.\n//\n// Regeln:\n//   - genau ein Inhaber, dazu Mitarbeiter bis NORA_PERSONEN\n//   - eine Person gehoert hoechstens zu EINER Firma (eindeutiger Index)\n//   - das Abo setzt NUR der Server (scripts/noraFreischalten.js,\n//     spaeter der Stripe-Webhook) - keine Route nimmt es aus req.body\n// ============================================\n\n'use strict';\n\nconst mongoose = require('mongoose');\n\nconst mitgliedSchema = new mongoose.Schema({\n  userId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },\n  rolle: { type: String, enum: ['inhaber', 'mitarbeiter'], required: true },\n  seit: { type: Date, default: Date.now }\n}, { _id: false });\n\nconst firmaSchema = new mongoose.Schema({\n  name: { type: String, required: true, trim: true, minlength: 2, maxlength: 120 },\n\n  mitglieder: {\n    type: [mitgliedSchema],\n    validate: [\n      {\n        validator: (liste) => Array.isArray(liste) && liste.length >= 1,\n        message: 'Eine Firma braucht mindestens eine Person'\n      },\n      {\n        validator: (liste) => Array.isArray(liste) && liste.filter((m) => m.rolle === 'inhaber').length === 1,\n        message: 'Eine Firma hat genau einen Inhaber'\n      },\n      {\n        validator: (liste) => {\n          const ids = (liste || []).map((m) => String(m.userId));\n          return new Set(ids).size === ids.length;\n        },\n        message: 'Eine Person steht doppelt in der Firma'\n      }\n    ]\n  },\n\n  abo: {\n    stufe: { type: String, enum: ['pilot', 'nora', null], default: null },\n    seit: { type: Date, default: null },\n    bis: { type: Date, default: null }\n  }\n}, { collection: 'nora_firmen', timestamps: true });\n\n// Eine Person gehoert hoechstens zu einer Firma.\nfirmaSchema.index(\n  { 'mitglieder.userId': 1 },\n  { unique: true, partialFilterExpression: { 'mitglieder.userId': { $exists: true } } }\n);\n\nmodule.exports = mongoose.models.NoraFirma || mongoose.model('NoraFirma', firmaSchema);\n",
  "src/nora/models/Verbrauch.js": "// ============================================\n// SYNORA - Nora: Verbrauch pro Firma und Monat\n// ============================================\n// Ein Dokument pro Firma und Monat (Schweizer Zeit). Am Monatsanfang\n// entsteht automatisch ein neues - so setzen sich die Limits zurueck,\n// ohne dass jemand etwas loeschen muss.\n//\n// Kosten in Millionstel Franken (ganze Zahlen), damit sich beim\n// Zusammenzaehlen keine Rundungsfehler aufsummieren.\n// ============================================\n\n'use strict';\n\nconst mongoose = require('mongoose');\nconst { firmaPflicht } = require('./firmaPflicht');\n\nconst zahlFeld = { type: Number, default: 0, min: 0 };\n\nconst verbrauchSchema = new mongoose.Schema({\n  firmaId: { type: mongoose.Schema.Types.ObjectId, ref: 'NoraFirma', required: true, immutable: true },\n  monat: { type: String, required: true, match: /^\\d{4}-\\d{2}$/ },\n  zaehler: {\n    pruefungen: zahlFeld,\n    experten: zahlFeld,\n    offerten: zahlFeld,\n    dokumente: zahlFeld,\n    fotos: zahlFeld,\n    preise: zahlFeld,\n    artefakte: zahlFeld,\n    akten: zahlFeld\n  },\n  kostenMikro: { type: Number, default: 0, min: 0 }\n}, { collection: 'nora_verbrauch', timestamps: true });\n\nverbrauchSchema.index({ firmaId: 1, monat: 1 }, { unique: true });\nverbrauchSchema.plugin(firmaPflicht);\n\nmodule.exports = mongoose.models.NoraVerbrauch || mongoose.model('NoraVerbrauch', verbrauchSchema);\n",
  "src/nora/services/verbrauch.js": "// ============================================\n// SYNORA - Nora: Limits und Kostenbremse pro Firma\n// ============================================\n// Ablauf fuer jede kostenpflichtige Aufgabe:\n//\n//   1. reservieren(firmaId, 'pruefung')   -> Zaehler +1, Reserve gebucht\n//      { ok: false, grund: 'LIMIT' | 'BREMSE' }  -> Aufgabe NICHT starten\n//   2. Arbeit machen (Modelle, Perplexity, SerpApi ...)\n//   3a. geklappt:   abrechnen(firmaId, reservierung, echteKostenChf)\n//   3b. gescheitert: zurueckgeben(firmaId, reservierung)\n//\n// WARUM IN EINEM SCHRITT\n//\n// Lesen, rechnen, schreiben haelt unter Last nicht: 50 gleichzeitige\n// Anfragen lesen denselben Stand und kommen alle durch. Darum steckt\n// die Pruefung IM Update: MongoDB erhoeht den Zaehler nur, wenn er\n// danach noch unter dem Limit und die Kosten unter der Bremse liegen.\n// Ein einzelnes Dokument wird von MongoDB atomar geaendert - eine\n// zweite Anfrage kann sich nicht dazwischenschieben.\n// ============================================\n\n'use strict';\n\nconst Verbrauch = require('../models/Verbrauch');\nconst { LIMITS, ZAEHLER, BREMSE_CHF, AUFGABEN, WARNUNG_AB } = require('../config');\n\nconst MIKRO = 1e6;\n\nfunction zuMikro(chf) {\n  const n = Number(chf);\n  if (!Number.isFinite(n)) throw new Error(`NORA: ungueltiger Betrag ${chf}`);\n  return Math.round(n * MIKRO);\n}\n\n/** Monat nach Schweizer Zeit, z. B. \"2026-11\". */\nfunction monatJetzt(jetzt = new Date()) {\n  const teile = new Intl.DateTimeFormat('en-CA', {\n    timeZone: 'Europe/Zurich', year: 'numeric', month: '2-digit'\n  }).formatToParts(jetzt);\n  const jahr = teile.find((t) => t.type === 'year').value;\n  const monat = teile.find((t) => t.type === 'month').value;\n  return `${jahr}-${monat}`;\n}\n\n// Alle Zaehler ausdruecklich auf 0. Wichtig: Ein fehlendes Feld wuerde\n// die Bedingung \"$lte Limit\" in MongoDB NICHT erfuellen.\nconst LEERER_MONAT = Object.freeze(ZAEHLER.reduce((o, name) => {\n  o[`zaehler.${name}`] = 0;\n  return o;\n}, { kostenMikro: 0 }));\n\n/** Legt das Monatsdokument an, falls es fehlt. Zwei gleichzeitige Aufrufe sind kein Problem. */\nasync function sicherstellen(firmaId, monat) {\n  try {\n    await Verbrauch.updateOne(\n      { firmaId, monat },\n      { $setOnInsert: { ...LEERER_MONAT } },\n      { upsert: true }\n    );\n  } catch (e) {\n    if (e && e.code === 11000) return; // der andere Aufruf war schneller\n    throw e;\n  }\n}\n\n/** Stand fuer die Anzeige. Kosten nur, wenn intern === true. */\nfunction standAus(doc, { intern = false } = {}) {\n  const z = (doc && doc.zaehler) || {};\n  const zaehler = {};\n  for (const name of ZAEHLER) {\n    const verbraucht = Number(z[name] || 0);\n    const limit = LIMITS[name];\n    const anteil = limit > 0 ? verbraucht / limit : 1;\n    zaehler[name] = {\n      verbraucht,\n      limit,\n      rest: Math.max(0, limit - verbraucht),\n      prozent: Math.min(100, Math.round(anteil * 100)),\n      warnung: anteil >= WARNUNG_AB\n    };\n  }\n  const stand = { monat: doc ? doc.monat : null, zaehler };\n  if (intern) {\n    stand.kostenChf = Number(((doc && doc.kostenMikro) || 0) / MIKRO);\n    stand.bremseChf = BREMSE_CHF;\n  }\n  return stand;\n}\n\nasync function reservieren(firmaId, aufgabe, { menge = 1, jetzt = new Date() } = {}) {\n  const def = AUFGABEN[aufgabe];\n  if (!def) throw new Error(`NORA: unbekannte Aufgabe \"${aufgabe}\"`);\n  if (!Number.isInteger(menge) || menge < 1 || menge > 1000) {\n    throw new Error(`NORA: ungueltige Menge ${menge}`);\n  }\n\n  const monat = monatJetzt(jetzt);\n  const reserveMikro = zuMikro(def.reserveChf * menge);\n  const bremseMikro = zuMikro(BREMSE_CHF);\n\n  const filter = { firmaId, monat, kostenMikro: { $lte: bremseMikro - reserveMikro } };\n  const plus = { kostenMikro: reserveMikro };\n  for (const name of def.zaehler) {\n    filter[`zaehler.${name}`] = { $lte: LIMITS[name] - menge };\n    plus[`zaehler.${name}`] = menge;\n  }\n\n  await sicherstellen(firmaId, monat);\n  const doc = await Verbrauch.findOneAndUpdate(filter, { $inc: plus }, { new: true }).lean();\n\n  if (doc) {\n    return { ok: true, firmaId: String(firmaId), aufgabe, menge, monat, reserveMikro, stand: standAus(doc) };\n  }\n\n  // Abgelehnt - nur noch fuer die Meldung herausfinden, warum.\n  const jetztDoc = await Verbrauch.findOne({ firmaId, monat }).lean();\n  const z = (jetztDoc && jetztDoc.zaehler) || {};\n  const voll = def.zaehler.filter((name) => Number(z[name] || 0) + menge > LIMITS[name]);\n  return {\n    ok: false,\n    grund: voll.length ? 'LIMIT' : 'BREMSE',\n    zaehler: voll,\n    aufgabe,\n    monat,\n    stand: standAus(jetztDoc)\n  };\n}\n\n/** Korrigiert die Reserve auf die echten Kosten. Gibt die Differenz in Franken zurueck. */\nasync function abrechnen(firmaId, reservierung, echteKostenChf) {\n  pruefeReservierung(firmaId, reservierung);\n  const diff = zuMikro(echteKostenChf) - reservierung.reserveMikro;\n  if (diff === 0) { reservierung.erledigt = true; return 0; }\n\n  const filter = { firmaId, monat: reservierung.monat };\n  if (diff < 0) filter.kostenMikro = { $gte: -diff }; // nie unter null\n\n  const r = await Verbrauch.updateOne(filter, { $inc: { kostenMikro: diff } });\n  reservierung.erledigt = true;\n  if (diff > 0) {\n    console.warn(`[nora] Firma ${firmaId}: ${reservierung.aufgabe} kostete CHF ${(diff / MIKRO).toFixed(4)} mehr als reserviert - Reserve in config.js pruefen`);\n  }\n  return r.modifiedCount === 1 ? diff / MIKRO : 0;\n}\n\n/** Gibt Zaehler und Reserve zurueck, wenn die Aufgabe gescheitert ist. */\nasync function zurueckgeben(firmaId, reservierung) {\n  pruefeReservierung(firmaId, reservierung);\n  const def = AUFGABEN[reservierung.aufgabe];\n  const filter = { firmaId, monat: reservierung.monat, kostenMikro: { $gte: reservierung.reserveMikro } };\n  const minus = { kostenMikro: -reservierung.reserveMikro };\n  for (const name of def.zaehler) {\n    filter[`zaehler.${name}`] = { $gte: reservierung.menge };\n    minus[`zaehler.${name}`] = -reservierung.menge;\n  }\n  const r = await Verbrauch.updateOne(filter, { $inc: minus });\n  reservierung.erledigt = true;\n  return r.modifiedCount === 1;\n}\n\nfunction pruefeReservierung(firmaId, reservierung) {\n  if (!reservierung || !reservierung.ok || !AUFGABEN[reservierung.aufgabe]) {\n    throw new Error('NORA: ungueltige Reservierung');\n  }\n  if (reservierung.erledigt) {\n    throw new Error('NORA: Reservierung wurde schon abgerechnet oder zurueckgegeben');\n  }\n  if (String(reservierung.firmaId) !== String(firmaId)) {\n    throw new Error('NORA: Reservierung gehoert zu einer anderen Firma');\n  }\n}\n\nasync function stand(firmaId, { intern = false, jetzt = new Date() } = {}) {\n  const monat = monatJetzt(jetzt);\n  const doc = await Verbrauch.findOne({ firmaId, monat }).lean();\n  const s = standAus(doc, { intern });\n  s.monat = monat;\n  return s;\n}\n\nmodule.exports = { reservieren, abrechnen, zurueckgeben, stand, monatJetzt, zuMikro, standAus };\n",
  "src/nora/services/firmaZugriff.js": "// ============================================\n// SYNORA - Nora: Zugriff nur auf die eigene Firma\n// ============================================\n// ladeFirma     haengt die Firma der eingeloggten Person an den\n//               Request (req.firma, req.noraRolle). Ohne Firma: 403.\n// nurMitAbo     laesst nur Firmen mit aktivem Abo (pilot, nora) durch.\n// nurInhaber    nur fuer den Inhaber (Personen verwalten).\n// firmaFilter   baut jeden Datenbank-Filter mit der eigenen firmaId.\n//               Jede Route MUSS ihre Abfragen damit bauen.\n// ============================================\n\n'use strict';\n\nconst mongoose = require('mongoose');\nconst Firma = require('../models/Firma');\nconst { ABO_STUFEN } = require('../config');\n\nasync function ladeFirma(req, res, next) {\n  // requireAuth laesst bei Datenbank-Ausfall einen Token ohne Nutzer\n  // durch. Fuer Nora reicht das nicht - ohne Nutzer keine Firma.\n  if (!req.user || !req.user._id || mongoose.connection.readyState !== 1) {\n    return res.status(503).json({\n      error: 'Nora ist gerade nicht erreichbar. Bitte gleich nochmals versuchen.',\n      code: 'DB_NICHT_BEREIT'\n    });\n  }\n\n  try {\n    const firma = await Firma.findOne({ 'mitglieder.userId': req.user._id });\n    if (!firma) {\n      return res.status(403).json({\n        error: 'Dieses Konto gehoert zu keiner Firma mit Nora.',\n        code: 'KEINE_FIRMA'\n      });\n    }\n    const ich = firma.mitglieder.find((m) => String(m.userId) === String(req.user._id));\n    req.firma = firma;\n    req.noraRolle = ich ? ich.rolle : null;\n    return next();\n  } catch (e) {\n    console.error('[nora] Firma laden:', e.message);\n    return res.status(500).json({ error: 'Interner Fehler', code: 'FIRMA_FEHLER' });\n  }\n}\n\nfunction aboAktiv(firma, jetzt = new Date()) {\n  return !!(firma && firma.abo && ABO_STUFEN.includes(firma.abo.stufe) &&\n    (!firma.abo.bis || new Date(firma.abo.bis) > jetzt));\n}\n\nfunction nurMitAbo(req, res, next) {\n  if (!aboAktiv(req.firma)) {\n    return res.status(402).json({\n      error: 'Nora ist fuer diese Firma nicht freigeschaltet.',\n      code: 'KEIN_ABO'\n    });\n  }\n  return next();\n}\n\nfunction nurInhaber(req, res, next) {\n  if (req.noraRolle !== 'inhaber') {\n    return res.status(403).json({ error: 'Nur der Inhaber darf das.', code: 'NUR_INHABER' });\n  }\n  return next();\n}\n\nfunction firmaFilter(req, filter = {}) {\n  if (!req || !req.firma || !req.firma._id) {\n    throw new Error('NORA: firmaFilter ohne geladene Firma');\n  }\n  if (filter && Object.prototype.hasOwnProperty.call(filter, 'firmaId') &&\n      String(filter.firmaId) !== String(req.firma._id)) {\n    throw new Error('NORA: fremde firmaId im Filter');\n  }\n  return { ...filter, firmaId: req.firma._id };\n}\n\nmodule.exports = { ladeFirma, nurMitAbo, nurInhaber, firmaFilter, aboAktiv };\n",
  "src/nora/services/freischalten.js": "// ============================================\n// SYNORA - Nora: Firmen freischalten (nur Server)\n// ============================================\n// Wird von scripts/noraFreischalten.js benutzt und vom Prueflauf\n// getestet. Keine Route ruft das auf: Das Abo setzt nur der Server.\n// ============================================\n\n'use strict';\n\nconst User = require('../../models/User');\nconst Firma = require('../models/Firma');\nconst verbrauch = require('./verbrauch');\nconst { ABO_STUFEN } = require('../config');\n\nconst EMAIL = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\n\nfunction fehler(code, text) {\n  const e = new Error(text);\n  e.code = code;\n  return e;\n}\n\nasync function nutzerPerMail(email) {\n  const mail = String(email || '').trim().toLowerCase();\n  if (!EMAIL.test(mail)) throw fehler('MAIL_UNGUELTIG', `Keine gueltige Mailadresse: ${email}`);\n  const nutzer = await User.findOne({ email: mail }).select('email').lean();\n  if (!nutzer) {\n    throw fehler('KONTO_FEHLT', `Kein SYNORA-Konto mit ${mail}. Die Person muss sich zuerst auf synora.li registrieren.`);\n  }\n  return nutzer;\n}\n\n/**\n * Legt die Firma an (falls noetig) und setzt das Abo.\n * Gibt { firma, neu, vorher } zurueck.\n */\nasync function freischalten({ email, name, stufe, jetzt = new Date() }) {\n  if (!ABO_STUFEN.includes(stufe)) {\n    throw fehler('STUFE_UNGUELTIG', `Stufe muss eine von diesen sein: ${ABO_STUFEN.join(', ')}`);\n  }\n  const nutzer = await nutzerPerMail(email);\n  const vorhanden = await Firma.findOne({ 'mitglieder.userId': nutzer._id });\n\n  if (vorhanden) {\n    const ich = vorhanden.mitglieder.find((m) => String(m.userId) === String(nutzer._id));\n    if (!ich || ich.rolle !== 'inhaber') {\n      throw fehler('NICHT_INHABER', `${nutzer.email} ist Mitarbeiter bei \"${vorhanden.name}\", nicht Inhaber.`);\n    }\n    const vorher = vorhanden.abo && vorhanden.abo.stufe ? vorhanden.abo.stufe : null;\n    vorhanden.abo = { stufe, seit: vorher === stufe && vorhanden.abo.seit ? vorhanden.abo.seit : jetzt, bis: null };\n    if (name && String(name).trim().length >= 2) vorhanden.name = String(name).trim();\n    await vorhanden.save();\n    return { firma: vorhanden, neu: false, vorher };\n  }\n\n  const firmenName = String(name || '').trim();\n  if (firmenName.length < 2) throw fehler('NAME_FEHLT', 'Fuer eine neue Firma braucht es einen Namen (mindestens 2 Zeichen).');\n\n  const firma = new Firma({\n    name: firmenName,\n    mitglieder: [{ userId: nutzer._id, rolle: 'inhaber', seit: jetzt }],\n    abo: { stufe, seit: jetzt, bis: null }\n  });\n  await firma.save();\n  return { firma, neu: true, vorher: null };\n}\n\n/** Beendet das Abo. Die Firma und ihre Daten bleiben bestehen. */\nasync function stoppen({ email }) {\n  const nutzer = await nutzerPerMail(email);\n  const firma = await Firma.findOne({ 'mitglieder.userId': nutzer._id });\n  if (!firma) throw fehler('KEINE_FIRMA', `${nutzer.email} gehoert zu keiner Firma.`);\n  const ich = firma.mitglieder.find((m) => String(m.userId) === String(nutzer._id));\n  if (!ich || ich.rolle !== 'inhaber') throw fehler('NICHT_INHABER', `${nutzer.email} ist nicht Inhaber von \"${firma.name}\".`);\n  const vorher = firma.abo ? firma.abo.stufe : null;\n  firma.abo = { stufe: null, seit: firma.abo ? firma.abo.seit : null, bis: null };\n  await firma.save();\n  return { firma, vorher };\n}\n\n/** Alle Firmen mit Abo, mit Verbrauch dieses Monats (intern, mit Kosten). */\nasync function liste({ jetzt = new Date() } = {}) {\n  const firmen = await Firma.find({ 'abo.stufe': { $in: [...ABO_STUFEN] } }).sort({ createdAt: 1 }).lean();\n  const ergebnis = [];\n  for (const f of firmen) {\n    const inhaber = f.mitglieder.find((m) => m.rolle === 'inhaber');\n    const u = inhaber ? await User.findById(inhaber.userId).select('email').lean() : null;\n    const s = await verbrauch.stand(f._id, { intern: true, jetzt });\n    ergebnis.push({\n      name: f.name,\n      inhaber: u ? u.email : '-',\n      personen: f.mitglieder.length,\n      stufe: f.abo.stufe,\n      seit: f.abo.seit,\n      pruefungen: s.zaehler.pruefungen,\n      experten: s.zaehler.experten,\n      kostenChf: s.kostenChf\n    });\n  }\n  return ergebnis;\n}\n\nmodule.exports = { freischalten, stoppen, liste };\n",
  "src/nora/routes/index.js": "// ============================================\n// SYNORA - Nora: Wege unter /api/nora\n// ============================================\n// Baustein N0 (14.11.2026): Firma, Personen, Verbrauch.\n//\n// Jeder Weg hier verlangt Login UND eine Firma. Es gibt bewusst\n// keinen Weg, der eine Firma anlegt oder ein Abo setzt - das macht\n// nur der Server (scripts/noraFreischalten.js).\n// ============================================\n\n'use strict';\n\nconst express = require('express');\nconst mongoose = require('mongoose');\nconst { requireAuth } = require('../../middleware/auth');\nconst User = require('../../models/User');\nconst Firma = require('../models/Firma');\nconst verbrauch = require('../services/verbrauch');\nconst { ladeFirma, nurInhaber, aboAktiv } = require('../services/firmaZugriff');\nconst { PERSONEN } = require('../config');\n\nconst router = express.Router();\nconst EMAIL = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\n\nrouter.use(requireAuth, ladeFirma);\n\n// Firma, Abo, Personen\nrouter.get('/firma', async (req, res) => {\n  try {\n    const f = req.firma;\n    const ids = f.mitglieder.map((m) => m.userId);\n    const nutzer = await User.find({ _id: { $in: ids } }).select('email firstname lastname').lean();\n    const proId = new Map(nutzer.map((u) => [String(u._id), u]));\n    res.json({\n      firma: {\n        name: f.name,\n        rolle: req.noraRolle,\n        abo: {\n          stufe: f.abo ? f.abo.stufe : null,\n          seit: f.abo ? f.abo.seit : null,\n          aktiv: aboAktiv(f)\n        },\n        personenLimit: PERSONEN,\n        mitglieder: f.mitglieder.map((m) => {\n          const u = proId.get(String(m.userId)) || {};\n          return {\n            userId: String(m.userId),\n            email: u.email || null,\n            name: [u.firstname, u.lastname].filter(Boolean).join(' ') || null,\n            rolle: m.rolle,\n            seit: m.seit\n          };\n        })\n      }\n    });\n  } catch (e) {\n    console.error('[nora] GET /firma:', e.message);\n    res.status(500).json({ error: 'Interner Fehler', code: 'FIRMA_FEHLER' });\n  }\n});\n\n// Verbrauch dieses Monats (ohne Kosten - die sind intern)\nrouter.get('/verbrauch', async (req, res) => {\n  try {\n    res.json(await verbrauch.stand(req.firma._id));\n  } catch (e) {\n    console.error('[nora] GET /verbrauch:', e.message);\n    res.status(500).json({ error: 'Interner Fehler', code: 'VERBRAUCH_FEHLER' });\n  }\n});\n\n// Person hinzufuegen (nur Inhaber). Die Person braucht ein SYNORA-Konto.\nrouter.post('/mitglieder', nurInhaber, async (req, res) => {\n  const email = String((req.body && req.body.email) || '').trim().toLowerCase();\n  if (!EMAIL.test(email) || email.length > 200) {\n    return res.status(400).json({ error: 'Bitte eine gueltige Mailadresse angeben.', code: 'MAIL_UNGUELTIG' });\n  }\n  try {\n    const nutzer = await User.findOne({ email }).select('_id').lean();\n    if (!nutzer) {\n      return res.status(404).json({\n        error: 'Diese Person braucht zuerst ein SYNORA-Konto mit dieser Mailadresse.',\n        code: 'KONTO_FEHLT'\n      });\n    }\n    if (req.firma.mitglieder.some((m) => String(m.userId) === String(nutzer._id))) {\n      return res.status(409).json({ error: 'Diese Person gehoert schon zur Firma.', code: 'SCHON_MITGLIED' });\n    }\n\n    // Atomar: nur wenn noch Platz ist und die Person nicht schon drin steht.\n    const neu = await Firma.findOneAndUpdate(\n      {\n        _id: req.firma._id,\n        [`mitglieder.${PERSONEN - 1}`]: { $exists: false },\n        'mitglieder.userId': { $ne: nutzer._id }\n      },\n      { $push: { mitglieder: { userId: nutzer._id, rolle: 'mitarbeiter', seit: new Date() } } },\n      { new: true }\n    );\n    if (!neu) {\n      return res.status(409).json({\n        error: `Mehr als ${PERSONEN} Personen sind im Abo nicht enthalten.`,\n        code: 'PERSONEN_LIMIT'\n      });\n    }\n    return res.status(201).json({ ok: true, personen: neu.mitglieder.length });\n  } catch (e) {\n    if (e && e.code === 11000) {\n      return res.status(409).json({ error: 'Diese Person gehoert schon zu einer anderen Firma.', code: 'ANDERE_FIRMA' });\n    }\n    console.error('[nora] POST /mitglieder:', e.message);\n    return res.status(500).json({ error: 'Interner Fehler', code: 'MITGLIED_FEHLER' });\n  }\n});\n\n// Person entfernen (nur Inhaber, nie den Inhaber selbst)\nrouter.delete('/mitglieder/:userId', nurInhaber, async (req, res) => {\n  const id = String(req.params.userId || '');\n  if (!mongoose.Types.ObjectId.isValid(id)) {\n    return res.status(400).json({ error: 'Ungueltige Person', code: 'ID_UNGUELTIG' });\n  }\n  try {\n    const r = await Firma.updateOne(\n      { _id: req.firma._id },\n      { $pull: { mitglieder: { userId: new mongoose.Types.ObjectId(id), rolle: 'mitarbeiter' } } }\n    );\n    if (r.modifiedCount !== 1) {\n      return res.status(404).json({ error: 'Diese Person ist nicht Mitarbeiter dieser Firma.', code: 'NICHT_GEFUNDEN' });\n    }\n    return res.json({ ok: true });\n  } catch (e) {\n    console.error('[nora] DELETE /mitglieder:', e.message);\n    return res.status(500).json({ error: 'Interner Fehler', code: 'MITGLIED_FEHLER' });\n  }\n});\n\nmodule.exports = router;\n",
  "src/routes/nora.js": "// ============================================\n// SYNORA - Nora (fuer Geschaefte)\n// ============================================\n// Nora wohnt in src/nora/. Diese Datei verbindet sie nur mit dem\n// Routen-Lader in server.js (ladeRoute('nora', '/api/nora')).\n// ============================================\n\n'use strict';\n\nmodule.exports = require('../nora/routes');\n",
  "scripts/noraFreischalten.js": "// ============================================\n// SYNORA - Nora: Firma freischalten, stoppen, auflisten\n// ============================================\n// Die ersten Wochen laeuft die Freischaltung von Hand, mit Absicht\n// (wie bei Kiara Plus). Spaeter macht das der Stripe-Webhook.\n//\n// Der Inhaber muss zuerst ein SYNORA-Konto haben (synora.li).\n//\n// Freischalten (legt die Firma an, falls es sie noch nicht gibt):\n//   node scripts/noraFreischalten.js inhaber@firma.ch \"Muster AG\" pilot\n//   node scripts/noraFreischalten.js inhaber@firma.ch \"Muster AG\" nora\n//\n// Abo beenden (Firma und Daten bleiben):\n//   node scripts/noraFreischalten.js --stopp inhaber@firma.ch\n//\n// Alle Firmen mit Abo und ihr Verbrauch diesen Monat:\n//   node scripts/noraFreischalten.js --liste\n// ============================================\n\n'use strict';\n\nconst path = require('path');\ntry { require('dotenv').config({ path: path.join(__dirname, '..', '.env') }); } catch (_) {}\nconst mongoose = require('mongoose');\n\nfunction hilfe() {\n  console.log('');\n  console.log('Aufruf:');\n  console.log('  node scripts/noraFreischalten.js inhaber@firma.ch \"Muster AG\" pilot');\n  console.log('  node scripts/noraFreischalten.js inhaber@firma.ch \"Muster AG\" nora');\n  console.log('  node scripts/noraFreischalten.js --stopp inhaber@firma.ch');\n  console.log('  node scripts/noraFreischalten.js --liste');\n  console.log('');\n}\n\n(async () => {\n  const args = process.argv.slice(2);\n  const uri = process.env.MONGODB_URI || process.env.MONGO_URI;\n  if (!uri) { console.log('\\nMONGODB_URI fehlt in der .env.\\n'); process.exit(1); }\n  if (!args.length) { hilfe(); process.exit(1); }\n\n  const { freischalten, stoppen, liste } = require(path.join(__dirname, '..', 'src', 'nora', 'services', 'freischalten.js'));\n\n  try {\n    await mongoose.connect(uri, { serverSelectionTimeoutMS: 10000 });\n\n    if (args[0] === '--liste') {\n      const firmen = await liste();\n      console.log('');\n      console.log(`Firmen mit Nora: ${firmen.length}`);\n      for (const f of firmen) {\n        const p = f.pruefungen;\n        const x = f.experten;\n        console.log(`  ${f.stufe.padEnd(6)} ${f.name.padEnd(30)} ${f.inhaber.padEnd(32)} ${f.personen} Pers.  ` +\n          `Pruefungen ${p.verbraucht}/${p.limit}  Experten ${x.verbraucht}/${x.limit}  Kosten CHF ${f.kostenChf.toFixed(2)}`);\n      }\n      console.log('');\n      return;\n    }\n\n    if (args[0] === '--stopp') {\n      const { firma, vorher } = await stoppen({ email: args[1] });\n      console.log('');\n      console.log(`OK  \"${firma.name}\": Abo ${vorher || '-'}  ->  beendet. Die Daten der Firma bleiben.`);\n      console.log('');\n      return;\n    }\n\n    const [email, name, stufe] = args;\n    const { firma, neu, vorher } = await freischalten({ email, name, stufe: String(stufe || '').trim().toLowerCase() });\n    console.log('');\n    if (neu) console.log(`OK  Neue Firma \"${firma.name}\" angelegt, Inhaber ${String(email).toLowerCase()}, Abo: ${firma.abo.stufe}`);\n    else console.log(`OK  \"${firma.name}\": Abo ${vorher || '-'}  ->  ${firma.abo.stufe}`);\n    console.log('    Nora gilt ab der naechsten Anfrage.');\n    console.log('');\n  } catch (e) {\n    console.log('');\n    console.log(e.code ? `NICHT GEMACHT (${e.code}): ${e.message}` : `Fehler: ${e.message}`);\n    console.log('');\n    process.exitCode = 1;\n  } finally {\n    await mongoose.connection.close().catch(() => {});\n  }\n})();\n",
  "scripts/noraProbe.js": "// ============================================\n// SYNORA - Nora: Prueflauf fuer Baustein N0\n// ============================================\n// Prueft gegen eine ECHTE MongoDB, ob die Grundlage haelt:\n//\n//   - keine Abfrage ohne firmaId\n//   - eine Person gehoert hoechstens zu einer Firma\n//   - Limits halten auch bei vielen gleichzeitigen Anfragen\n//   - Kostenbremse haelt auch bei vielen gleichzeitigen Anfragen\n//   - Firma A sieht nie die Daten von Firma B (ueber die echten Wege)\n//   - Personen-Limit, Rollen, Freischalten, Stoppen\n//\n// SICHER: Der Lauf benutzt eine EIGENE Datenbank namens\n// \"synora_nora_probe\" auf deinem Cluster - nicht die echte. Er prueft\n// den Namen, bevor er irgendetwas schreibt, und loescht diese eine\n// Datenbank am Anfang und am Ende. Echte Daten werden nicht beruehrt.\n// Er benutzt kleine Test-Limits (20 Pruefungen, 5 Experten, CHF 10)\n// und einen eigenen Zufalls-Schluessel fuer die Logins.\n//\n// Aufruf im Ordner synora-backend-main:\n//   node scripts/noraProbe.js\n// ============================================\n\n'use strict';\n\nconst path = require('path');\nconst crypto = require('crypto');\ntry { require('dotenv').config({ path: path.join(__dirname, '..', '.env') }); } catch (_) {}\n\n// Test-Werte - NACH dotenv setzen, damit sie gewinnen.\nprocess.env.NORA_PRUEFUNGEN = '20';\nprocess.env.NORA_EXPERTEN = '5';\nprocess.env.NORA_BREMSE_CHF = '10';\nprocess.env.NORA_PERSONEN = '3';\nprocess.env.JWT_SECRET = crypto.randomBytes(32).toString('hex');\n\nconst PROBE_DB = 'synora_nora_probe';\nconst mongoose = require('mongoose');\nconst express = require('express');\nconst jwt = require('jsonwebtoken');\n\nconst wurzel = path.join(__dirname, '..');\nconst User = require(path.join(wurzel, 'src', 'models', 'User.js'));\nconst Firma = require(path.join(wurzel, 'src', 'nora', 'models', 'Firma.js'));\nconst Verbrauch = require(path.join(wurzel, 'src', 'nora', 'models', 'Verbrauch.js'));\nconst verbrauch = require(path.join(wurzel, 'src', 'nora', 'services', 'verbrauch.js'));\nconst { freischalten, stoppen, liste } = require(path.join(wurzel, 'src', 'nora', 'services', 'freischalten.js'));\nconst noraRouten = require(path.join(wurzel, 'src', 'routes', 'nora.js'));\n\nlet gut = 0;\nlet schlecht = 0;\nfunction pruefe(name, bedingung, info = '') {\n  if (bedingung) { gut++; console.log(`  OK      ${name}`); }\n  else { schlecht++; console.log(`  FEHLER  ${name}${info ? '   (' + info + ')' : ''}`); }\n}\nasync function wirdAbgelehnt(versprechen) {\n  try { await versprechen; return false; } catch (_) { return true; }\n}\nasync function fehlerCode(funktion) {\n  try { await funktion(); return null; } catch (e) { return e.code || e.message; }\n}\n\nasync function datenbankLeeren() {\n  if (mongoose.connection.db.databaseName !== PROBE_DB) {\n    throw new Error(`Sicherheitsstopp: verbunden mit \"${mongoose.connection.db.databaseName}\" statt \"${PROBE_DB}\"`);\n  }\n  await mongoose.connection.db.dropDatabase();\n}\n\n(async () => {\n  const uri = process.env.MONGODB_URI || process.env.MONGO_URI;\n  if (!uri) { console.log('\\nMONGODB_URI fehlt in der .env.\\n'); process.exit(1); }\n  if (typeof fetch !== 'function') { console.log('\\nDieser Prueflauf braucht Node 18 oder neuer (node -v).\\n'); process.exit(1); }\n\n  let server = null;\n  console.log('');\n  console.log('SYNORA - Nora Prueflauf N0');\n  console.log('==========================');\n  console.log(`Datenbank: ${PROBE_DB} (eigene Pruef-Datenbank, nicht die echte)`);\n\n  try {\n    await mongoose.connect(uri, { dbName: PROBE_DB, serverSelectionTimeoutMS: 15000 });\n    await datenbankLeeren();\n    await User.syncIndexes();\n    await Firma.syncIndexes();\n    await Verbrauch.syncIndexes();\n\n    // ---------- Personen ----------\n    const mail = (n) => `${n}@nora-probe.synora.li`;\n    const namen = ['a1', 'a2', 'b1', 'b2', 'b3', 'c1', 'x', 'p1', 'p2', 'p3', 'p4', 'p5'];\n    const u = {};\n    for (const n of namen) {\n      u[n] = await User.create({ email: mail(n), password: 'Probe-Passwort-2026!x' });\n    }\n    const token = (n) => jwt.sign({ userId: u[n]._id, email: u[n].email }, process.env.JWT_SECRET, { expiresIn: '10m' });\n\n    // ---------- 1. Firmenpflicht ----------\n    console.log('\\n1. Keine Abfrage ohne firmaId');\n    const fremd = new mongoose.Types.ObjectId();\n    pruefe('find({}) wird abgelehnt', await wirdAbgelehnt(Verbrauch.find({})));\n    pruefe('firmaId mit $exists wird abgelehnt', await wirdAbgelehnt(Verbrauch.findOne({ firmaId: { $exists: true } })));\n    pruefe('firmaId mit $in wird abgelehnt', await wirdAbgelehnt(Verbrauch.find({ firmaId: { $in: [fremd] } })));\n    pruefe('countDocuments ohne firmaId wird abgelehnt', await wirdAbgelehnt(Verbrauch.countDocuments({ monat: '2026-11' })));\n    pruefe('firmaId aendern wird abgelehnt', await wirdAbgelehnt(Verbrauch.updateOne({ firmaId: fremd }, { $set: { firmaId: new mongoose.Types.ObjectId() } })));\n    pruefe('Aggregation ohne $match firmaId wird abgelehnt', await wirdAbgelehnt(Verbrauch.aggregate([{ $match: {} }])));\n    pruefe('find mit eigener firmaId geht', !(await wirdAbgelehnt(Verbrauch.find({ firmaId: fremd }))));\n\n    // ---------- 2. Firmen anlegen ----------\n    console.log('\\n2. Freischalten');\n    const fa = await freischalten({ email: mail('a1'), name: 'Probe A AG', stufe: 'pilot' });\n    pruefe('Firma A neu angelegt (pilot)', fa.neu && fa.firma.abo.stufe === 'pilot');\n    const fb = await freischalten({ email: mail('b1'), name: 'Probe B GmbH', stufe: 'nora' });\n    const fc = await freischalten({ email: mail('c1'), name: 'Probe C', stufe: 'nora' });\n    pruefe('Firma B und C angelegt', fb.neu && fc.neu);\n    const fa2 = await freischalten({ email: mail('a1'), name: '', stufe: 'nora' });\n    pruefe('Firma A: pilot -> nora, keine zweite Firma', !fa2.neu && fa2.vorher === 'pilot' && fa2.firma.abo.stufe === 'nora' && fa2.firma.name === 'Probe A AG');\n    pruefe('unbekannte Mail -> KONTO_FEHLT', (await fehlerCode(() => freischalten({ email: mail('gibtsnicht'), name: 'X AG', stufe: 'nora' }))) === 'KONTO_FEHLT');\n    pruefe('falsche Stufe -> STUFE_UNGUELTIG', (await fehlerCode(() => freischalten({ email: mail('a1'), name: 'X', stufe: 'gold' }))) === 'STUFE_UNGUELTIG');\n    const doppelt = await fehlerCode(() => Firma.create({ name: 'Doppelt AG', mitglieder: [{ userId: u.a1._id, rolle: 'inhaber' }] }));\n    pruefe('dieselbe Person in zweiter Firma -> abgelehnt', doppelt === 11000, String(doppelt));\n    const A = fa.firma._id;\n    const B = fb.firma._id;\n    const C = fc.firma._id;\n\n    // ---------- 3. Limits unter Last ----------\n    console.log('\\n3. Limits bei vielen gleichzeitigen Anfragen');\n    const r3 = await Promise.all(Array.from({ length: 60 }, () => verbrauch.reservieren(A, 'pruefung')));\n    const ok3 = r3.filter((r) => r.ok);\n    pruefe('60 gleichzeitig, Limit 20 -> genau 20 durch', ok3.length === 20, `${ok3.length} durch`);\n    pruefe('die anderen 40 mit Grund LIMIT', r3.filter((r) => !r.ok && r.grund === 'LIMIT').length === 40);\n    let sA = await verbrauch.stand(A);\n    pruefe('Zaehler A steht auf 20', sA.zaehler.pruefungen.verbraucht === 20);\n\n    const r4 = await Promise.all(Array.from({ length: 10 }, () => verbrauch.reservieren(B, 'expertenpruefung')));\n    pruefe('10 Expertenpruefungen, Limit 5 -> genau 5', r4.filter((r) => r.ok).length === 5);\n    const r4b = await Promise.all(Array.from({ length: 10 }, () => verbrauch.reservieren(B, 'pruefung')));\n    pruefe('danach 10 normale Pruefungen -> alle durch', r4b.filter((r) => r.ok).length === 10);\n    let sB = await verbrauch.stand(B);\n    pruefe('Firma B: 15 Pruefungen, davon 5 Experten', sB.zaehler.pruefungen.verbraucht === 15 && sB.zaehler.experten.verbraucht === 5);\n\n    // ---------- 4. Kostenbremse unter Last ----------\n    console.log('\\n4. Kostenbremse bei vielen gleichzeitigen Anfragen');\n    const r5 = await Promise.all(Array.from({ length: 100 }, () => verbrauch.reservieren(C, 'akte')));\n    const ok5 = r5.filter((r) => r.ok).length;\n    pruefe('100 gleichzeitig, Bremse CHF 10, je 0.15 -> genau 66 durch', ok5 === 66, `${ok5} durch`);\n    pruefe('die anderen mit Grund BREMSE', r5.filter((r) => !r.ok && r.grund === 'BREMSE').length === 34);\n    const sC = await verbrauch.stand(C, { intern: true });\n    pruefe('Kosten C = CHF 9.90, nie ueber 10', Math.abs(sC.kostenChf - 9.9) < 1e-9, String(sC.kostenChf));\n\n    // ---------- 5. Zurueckgeben und Abrechnen ----------\n    console.log('\\n5. Zurueckgeben und Abrechnen');\n    const eine = ok3[0];\n    pruefe('Reservierung einer fremden Firma -> abgelehnt', await wirdAbgelehnt(verbrauch.zurueckgeben(B, eine)));\n    pruefe('gescheiterte Aufgabe zurueckgeben', await verbrauch.zurueckgeben(A, eine));\n    pruefe('zweimal zurueckgeben -> abgelehnt', await wirdAbgelehnt(verbrauch.zurueckgeben(A, eine)));\n    sA = await verbrauch.stand(A, { intern: true });\n    pruefe('Zaehler A wieder 19, Kosten 19 x 0.40', sA.zaehler.pruefungen.verbraucht === 19 && Math.abs(sA.kostenChf - 7.6) < 1e-9, `${sA.zaehler.pruefungen.verbraucht} / ${sA.kostenChf}`);\n    const neu = await verbrauch.reservieren(A, 'pruefung');\n    await verbrauch.abrechnen(A, neu, 0.31);\n    sA = await verbrauch.stand(A, { intern: true });\n    pruefe('Abrechnen: Reserve 0.40 auf echte 0.31 korrigiert', Math.abs(sA.kostenChf - 7.91) < 1e-9, String(sA.kostenChf));\n    pruefe('zweimal abrechnen -> abgelehnt', await wirdAbgelehnt(verbrauch.abrechnen(A, neu, 0.31)));\n\n    // ---------- 6. Monate ----------\n    console.log('\\n6. Neuer Monat, neue Limits');\n    const spaeter = await verbrauch.reservieren(A, 'pruefung', { jetzt: new Date('2030-01-15T12:00:00Z') });\n    pruefe('im Januar 2030 wieder frei', spaeter.ok && spaeter.monat === '2030-01' && spaeter.stand.zaehler.pruefungen.verbraucht === 1);\n    pruefe('Monatswechsel nach Schweizer Zeit (30.11. 23:30 UTC = Dezember)', verbrauch.monatJetzt(new Date('2026-11-30T23:30:00Z')) === '2026-12');\n\n    // ---------- 7. Die echten Wege ----------\n    console.log('\\n7. Wege unter /api/nora - jede Firma sieht nur sich');\n    const app = express();\n    app.use(express.json());\n    app.use('/api/nora', noraRouten);\n    server = await new Promise((ok) => { const s = app.listen(0, () => ok(s)); });\n    const basis = `http://127.0.0.1:${server.address().port}/api/nora`;\n    async function ruf(methode, weg, wer, body) {\n      const kopf = { 'content-type': 'application/json' };\n      if (wer) kopf.authorization = `Bearer ${token(wer)}`;\n      const antwort = await fetch(basis + weg, { method: methode, headers: kopf, body: body ? JSON.stringify(body) : undefined });\n      let daten = null;\n      try { daten = await antwort.json(); } catch (_) {}\n      return { status: antwort.status, daten: daten || {} };\n    }\n\n    pruefe('ohne Login -> 401', (await ruf('GET', '/firma')).status === 401);\n    const ohneFirma = await ruf('GET', '/firma', 'x');\n    pruefe('Konto ohne Firma -> 403 KEINE_FIRMA', ohneFirma.status === 403 && ohneFirma.daten.code === 'KEINE_FIRMA');\n    const gA = await ruf('GET', '/firma', 'a1');\n    pruefe('a1 sieht Firma A, als Inhaber, Abo aktiv', gA.status === 200 && gA.daten.firma.name === 'Probe A AG' && gA.daten.firma.rolle === 'inhaber' && gA.daten.firma.abo.aktiv === true);\n    const vA = await ruf('GET', '/verbrauch', 'a1');\n    const vB = await ruf('GET', '/verbrauch', 'b1');\n    pruefe('a1 sieht den Verbrauch von A (20 Pruefungen, 0 Experten)', vA.daten.zaehler && vA.daten.zaehler.pruefungen.verbraucht === 20 && vA.daten.zaehler.experten.verbraucht === 0);\n    pruefe('b1 sieht den Verbrauch von B (15 Pruefungen, 5 Experten)', vB.daten.zaehler && vB.daten.zaehler.pruefungen.verbraucht === 15 && vB.daten.zaehler.experten.verbraucht === 5);\n    pruefe('Kunden sehen keine Kosten', vA.daten.kostenChf === undefined && vB.daten.kostenChf === undefined);\n\n    pruefe('b1 nimmt a2 auf -> 201', (await ruf('POST', '/mitglieder', 'b1', { email: mail('a2') })).status === 201);\n    const andere = await ruf('POST', '/mitglieder', 'a1', { email: mail('a2') });\n    pruefe('a1 will a2 auch -> 409 ANDERE_FIRMA', andere.status === 409 && andere.daten.code === 'ANDERE_FIRMA', `${andere.status} ${andere.daten.code}`);\n    const keinInhaber = await ruf('POST', '/mitglieder', 'a2', { email: mail('b2') });\n    pruefe('Mitarbeiter a2 darf niemanden aufnehmen -> 403', keinInhaber.status === 403 && keinInhaber.daten.code === 'NUR_INHABER');\n    const gA2 = await ruf('GET', '/firma', 'a2');\n    pruefe('a2 sieht jetzt Firma B, als Mitarbeiter', gA2.daten.firma && gA2.daten.firma.name === 'Probe B GmbH' && gA2.daten.firma.rolle === 'mitarbeiter');\n    pruefe('b1 nimmt b2 auf -> 3 Personen', (await ruf('POST', '/mitglieder', 'b1', { email: mail('b2') })).daten.personen === 3);\n    const zuViele = await ruf('POST', '/mitglieder', 'b1', { email: mail('b3') });\n    pruefe('vierte Person -> 409 PERSONEN_LIMIT', zuViele.status === 409 && zuViele.daten.code === 'PERSONEN_LIMIT');\n    pruefe('unbekannte Mail -> 404 KONTO_FEHLT', (await ruf('POST', '/mitglieder', 'b1', { email: mail('niemand') })).daten.code === 'KONTO_FEHLT');\n    pruefe('kaputte Mail -> 400', (await ruf('POST', '/mitglieder', 'b1', { email: 'kein-mail' })).status === 400);\n    pruefe('Inhaber kann nicht entfernt werden', (await ruf('DELETE', `/mitglieder/${u.b1._id}`, 'b1')).status === 404);\n    pruefe('a1 kann a2 (Firma B) nicht entfernen', (await ruf('DELETE', `/mitglieder/${u.a2._id}`, 'a1')).status === 404);\n    pruefe('b1 entfernt a2', (await ruf('DELETE', `/mitglieder/${u.a2._id}`, 'b1')).status === 200);\n    pruefe('a2 hat danach keine Firma mehr', (await ruf('GET', '/firma', 'a2')).daten.code === 'KEINE_FIRMA');\n\n    const gleichzeitig = await Promise.all(['p1', 'p2', 'p3', 'p4', 'p5'].map((n) => ruf('POST', '/mitglieder', 'b1', { email: mail(n) })));\n    pruefe('5 gleichzeitig, 1 Platz frei -> genau 1 aufgenommen', gleichzeitig.filter((r) => r.status === 201).length === 1);\n    const fB = await Firma.findById(B).lean();\n    pruefe('Firma B hat genau 3 Personen', fB.mitglieder.length === 3);\n    pruefe('kein Weg, um ein Abo zu setzen', (await ruf('PATCH', '/firma', 'b1', { abo: { stufe: 'nora' } })).status === 404);\n\n    // ---------- 8. Stoppen und Liste ----------\n    console.log('\\n8. Abo stoppen und Liste');\n    await stoppen({ email: mail('c1') });\n    const gC = await ruf('GET', '/firma', 'c1');\n    pruefe('Firma C: Abo beendet, Daten bleiben', gC.status === 200 && gC.daten.firma.abo.aktiv === false);\n    const l = await liste();\n    pruefe('Liste zeigt A und B, nicht C', l.length === 2 && l.some((f) => f.name === 'Probe A AG') && l.some((f) => f.name === 'Probe B GmbH'));\n  } catch (e) {\n    schlecht++;\n    console.log('');\n    console.log(`ABBRUCH: ${e.message}`);\n    if (/not authorized|Unauthorized/i.test(e.message)) {\n      console.log('Dein Atlas-Datenbanknutzer darf die Pruef-Datenbank nicht anlegen.');\n      console.log('Bitte diese Meldung schicken - dann loesen wir das anders.');\n    }\n  } finally {\n    if (server) await new Promise((ok) => server.close(ok));\n    try { if (mongoose.connection.readyState === 1) await datenbankLeeren(); } catch (_) {}\n    await mongoose.connection.close().catch(() => {});\n  }\n\n  console.log('');\n  console.log('==========================');\n  console.log(`  ${gut} OK, ${schlecht} FEHLER`);\n  console.log(schlecht === 0\n    ? '  Grundlage N0 haelt. Pruef-Datenbank wieder geloescht.'\n    : '  Bitte die ganze Ausgabe schicken.');\n  console.log('');\n  process.exit(schlecht === 0 ? 0 : 1);\n})();\n"
};

const ANKER = "  ladeRoute('rueckmeldung', '/api');";
const EINTRAG = [
  '  // NEU am 14.11.2026: Nora fuer Geschaefte (Etappe 1, Baustein N0)',
  '  // Nicht kritisch - faellt Nora aus, laeuft Kiara weiter.',
  "  ladeRoute('nora', '/api/nora');",
  ''
];
const MERKMAL = "ladeRoute('nora', '/api/nora')";

function stempel() {
  const d = new Date();
  const z = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${z(d.getMonth() + 1)}-${z(d.getDate())}-${z(d.getHours())}-${z(d.getMinutes())}`;
}

function abbruch(text) {
  console.log('');
  console.log('ABBRUCH: ' + text);
  console.log('Es wurde nichts geaendert.');
  console.log('');
  process.exit(1);
}

console.log('');
console.log('SYNORA - Nora Baustein N0 (Grundlage)');
console.log('=====================================');

// ---------- 1. Richtiger Ordner? ----------
const paketPfad = path.join(WURZEL, 'package.json');
const serverPfad = path.join(WURZEL, 'src', 'server.js');
if (!fs.existsSync(paketPfad) || !fs.existsSync(serverPfad)) {
  abbruch('Bitte im Ordner synora-backend-main starten (package.json und src/server.js fehlen hier).');
}
let paket;
try { paket = JSON.parse(fs.readFileSync(paketPfad, 'utf8')); } catch (e) { abbruch('package.json ist nicht lesbar: ' + e.message); }
if (paket.name !== 'synora-v2-backend') abbruch(`Das ist nicht das SYNORA-Backend (package.json: "${paket.name}").`);

// ---------- 2. Pruefen, bevor irgendetwas geschrieben wird ----------
console.log('\nPruefung:');
const neueDateien = [];
for (const [rel, inhalt] of Object.entries(DATEIEN)) {
  const ziel = path.join(WURZEL, ...rel.split('/'));
  if (fs.existsSync(ziel)) {
    const vorhanden = fs.readFileSync(ziel, 'utf8').replace(/\r\n/g, '\n');
    if (vorhanden === inhalt) { console.log(`  schon da  ${rel}`); continue; }
    abbruch(`${rel} gibt es schon, mit anderem Inhalt. Ich ueberschreibe keine fremde Datei - bitte Bescheid geben.`);
  }
  neueDateien.push({ rel, ziel, inhalt });
  console.log(`  neu       ${rel}`);
}

const serverRoh = fs.readFileSync(serverPfad, 'utf8');
const EOL = serverRoh.includes('\r\n') ? '\r\n' : '\n';
const serverText = serverRoh.replace(/\r\n/g, '\n');
let serverNeu = null;
if (serverText.includes(MERKMAL)) {
  console.log('  schon da  src/server.js (Nora angemeldet)');
} else {
  const zeilen = serverText.split('\n');
  const treffer = zeilen.reduce((a, z, i) => (z === ANKER ? a.concat(i) : a), []);
  if (treffer.length !== 1) {
    abbruch(`In src/server.js steht die Zeile ${ANKER.trim()} ${treffer.length}-mal statt genau einmal.`);
  }
  zeilen.splice(treffer[0], 0, ...EINTRAG);
  serverNeu = zeilen.join('\n');
  console.log('  aendern   src/server.js (Nora anmelden)');
}

if (!neueDateien.length && serverNeu === null) {
  console.log('\nAlles ist schon eingebaut. Nichts zu tun.');
  console.log('Naechster Schritt: node scripts/noraProbe.js\n');
  process.exit(0);
}

// ---------- 3. Schreiben, mit Rueckweg ----------
const angelegt = [];
const neueOrdner = [];
let sicherung = null;

function zurueckstellen() {
  for (const datei of angelegt.reverse()) { try { fs.unlinkSync(datei); } catch (_) {} }
  for (const ordner of neueOrdner.reverse()) { try { fs.rmdirSync(ordner); } catch (_) {} }
  if (sicherung) { try { fs.copyFileSync(sicherung, serverPfad); } catch (_) {} }
}

function scheitern(text) {
  zurueckstellen();
  console.log('');
  console.log('FEHLER: ' + text);
  console.log('Alles wurde zurueckgestellt. Bitte die ganze Ausgabe schicken.');
  console.log('');
  process.exit(1);
}

try {
  if (serverNeu !== null) {
    sicherung = `${serverPfad}.sicherung-${stempel()}`;
    fs.copyFileSync(serverPfad, sicherung);
    console.log('\nSicherung:');
    console.log('  ' + path.relative(WURZEL, sicherung));
  }

  for (const d of neueDateien) {
    let ordner = path.dirname(d.ziel);
    const fehlend = [];
    while (!fs.existsSync(ordner)) { fehlend.unshift(ordner); ordner = path.dirname(ordner); }
    for (const o of fehlend) { fs.mkdirSync(o); neueOrdner.push(o); }
    fs.writeFileSync(d.ziel, d.inhalt, 'utf8');
    angelegt.push(d.ziel);
  }
  if (serverNeu !== null) fs.writeFileSync(serverPfad, serverNeu.split('\n').join(EOL), 'utf8');
} catch (e) {
  scheitern('Schreiben fehlgeschlagen: ' + e.message);
}

// ---------- 4. Gegenprobe ----------
console.log('\nGegenprobe:');
for (const d of neueDateien) {
  const zurueck = fs.readFileSync(d.ziel, 'utf8');
  if (zurueck !== d.inhalt) scheitern(`${d.rel} steht nicht so in der Datei, wie geschrieben.`);
}
const serverJetzt = fs.readFileSync(serverPfad, 'utf8');
if (serverJetzt.split(MERKMAL).length - 1 !== 1) scheitern('Nora steht nicht genau einmal in src/server.js.');
console.log(`  OK       ${neueDateien.length} neue Datei(en) und server.js stehen so da wie geplant`);

const zuPruefen = Object.keys(DATEIEN).map((rel) => path.join(WURZEL, ...rel.split('/'))).concat(serverPfad);
for (const datei of zuPruefen) {
  const r = spawnSync(process.execPath, ['--check', datei], { encoding: 'utf8' });
  if (r.status !== 0) scheitern(`Syntaxfehler in ${path.relative(WURZEL, datei)}:\n${r.stderr}`);
}
console.log(`  OK       Syntax aller ${zuPruefen.length} Dateien`);

const ladeprobe = spawnSync(process.execPath, ['-e', [
  "require('./src/routes/nora');",
  "require('./src/nora/services/freischalten');",
  "const c = require('./src/nora/config');",
  "if (c.LIMITS.pruefungen < 1 || c.BREMSE_CHF <= 0) throw new Error('Limits unplausibel');",
  "console.log('LADEN_OK ' + c.LIMITS.pruefungen + ' ' + c.LIMITS.experten + ' ' + c.BREMSE_CHF);"
].join(' ')], { cwd: WURZEL, encoding: 'utf8', timeout: 60000 });
const ladeAusgabe = (ladeprobe.stdout || '').trim().split('\n').pop() || '';
if (ladeprobe.status !== 0 || !ladeAusgabe.startsWith('LADEN_OK')) {
  scheitern(`Nora laesst sich nicht laden:\n${(ladeprobe.stderr || ladeprobe.stdout || '').slice(0, 1500)}`);
}
const [, p, x, b] = ladeAusgabe.split(' ');
console.log(`  OK       Nora laedt (Limits: ${p} Pruefungen, ${x} Experten, Bremse CHF ${b})`);

console.log('');
console.log('FERTIG. Nora N0 ist eingebaut, aber noch nicht hochgeladen.');
console.log('');
console.log('NAECHSTER SCHRITT - der Prueflauf gegen eine eigene Pruef-Datenbank:');
console.log('  node scripts/noraProbe.js');
console.log('');
